}

// 求不相交区间的最大个数
function disjoint(ranges) {
  let count = 1; // 至少一个
  ranges.sort((a, b) => a[1] - b[1]);

  // console.log(ranges);

  let t = ranges[0][1];
  for (let i = 1; i < ranges.length; i++) {
    let [l, r] = ranges[i];
    if (t < l) {
